import type { SeedExercise } from "./content";
import type { Json, Language } from "../src/lib/types";

// Contrato estructural idéntico al acordado con plataforma. No contiene soluciones.
// Al integrar, SeedExercise incorpora estos campos aditivos desde prisma/content.ts.
type ProjectFile = { path: string; content: string; readOnly?: boolean };
type ProjectDefinition = { version: 1; entrypoint: string; files: ProjectFile[]; testEntrypoint?: string; previousStep?: string };
export type ProjectLesson = Omit<SeedExercise, "tests"> & {
  projects: Record<Language, ProjectDefinition>;
  projectSolutions: Record<Language, ProjectFile[]>;
  tests: (SeedExercise["tests"][number] & { expectedFiles?: ProjectFile[] })[];
};
// Expectativas editoriales literales: no se derivan ejecutando la referencia
// ni serializando su retorno. El contrato compartido solo admite rutas nuevas.
const producedFiles: Record<string, { path: string; contents: string[] }> = {
  "escribe-archivo": { path: "resultado.txt", contents: ["Hola Ada", "Hola", "Hola!"] },
  "guarda-recupera": { path: "guardado.json", contents: ["[1,2]", "[]", "[-3,0,3]"] },
  "actualiza-persistidos": { path: "guardado.json", contents: ["[2,4,6]", "[2,4]", "[2,4,-1,0]"] },
  "inventario-persistente": { path: "guardado.json", contents: ['{"pan":1,"sal":3}', '{"pan":2}', '{"pan":3}'] },
  "agenda-almacenamiento": { path: "guardado.json", contents: ['[{"titulo":"leer","hecha":true}]', '[{"titulo":"leer","hecha":false}]', '[{"titulo":"leer","hecha":false},{"titulo":"andar","hecha":false}]'] },
  "agenda-regresion": { path: "guardado.json", contents: ['[{"titulo":"leer","hecha":true}]', '[{"titulo":"leer","hecha":false}]', '[{"titulo":"leer","hecha":false},{"titulo":"andar","hecha":false}]', '[{"titulo":"leer","hecha":true}]', '[{"titulo":"leer","hecha":false},{"titulo":"andar","hecha":true}]'] },
};
export const fundamentalsProjectLessons = new Map<string, ProjectLesson>();
type Code = { python: string; javascript: string; typescript: string };
type ProjectOptions = {
  key: string; problem: string; input: string; output: string; code: Code;
  helpers?: { name: string; code: Code; editable?: boolean; starter?: Code }[];
  resources?: ProjectFile[]; cases: [Json, Json][];
  hints: [string, string, string]; theory: string; previous?: string;
  starter?: Code; ownTests?: Code;
};
const extensions: Record<Language, string> = { python: "py", javascript: "js", typescript: "ts" };
export function projectLesson(d: ProjectOptions) {
  const produced = producedFiles[d.key];
  if (produced && produced.contents.length !== d.cases.length) throw new Error(`Faltan expectativas de archivo: ${d.key}`);
  const signature = `export function solve(data: ${d.input}): ${d.output}`;
  const wrap = (language: Language, body: string) => {
    if (language === "python") return `def solve(data):\n${body.split("\n").map(line => `    ${line}`).join("\n")}\n`;
    if (language === "javascript") return `function solve(data) {\n${body}\n}\nmodule.exports = solve;\n`;
    // El formato editorial común declara dependencias junto al cuerpo. En TS
    // se emiten imports reales al nivel de módulo para comprobar también el
    // contrato entre archivos, no solo una aserción de tipo de require.
    const imports: string[] = [];
    const functionBody = body.replace(/const \{ ([\w, ]+) \} = require\('(\.\/\w+)'\) as \{ [^\n]+ \};\n/g, (_, names: string, path: string) => {
      imports.push(`import { ${names} } from '${path}';`);
      return "";
    });
    return `${imports.length ? imports.join("\n") + "\n" : ""}${signature} {\n${functionBody}\n}\n`;
  };
  const fallback = d.output === "number" ? "0" : d.output.endsWith("[]") ? "[]" : d.output === "string" ? '""' : d.output.includes("stock") ? "{ stock: {}, rechazados: 0 }" : d.output.includes("rechazados") ? "{ total: 0, porCategoria: {}, rechazados: 0 }" : "{ total: 0, porCategoria: {} }";
  const projects = {} as Record<Language, ProjectDefinition>;
  const projectSolutions = {} as Record<Language, ProjectFile[]>;
  const solutions = {} as Code;
  const starters = {} as Code;
  for (const language of ["python", "javascript", "typescript"] as const) {
    const ext = extensions[language];
    solutions[language] = wrap(language, d.code[language]);
    starters[language] = wrap(language, d.starter?.[language] ?? (language === "python" ? "# Completa los requisitos; conserva el contrato.\nreturn None" : `// Completa los requisitos; conserva el contrato.\nreturn ${language === "typescript" ? fallback : "null"};`));
    const files: ProjectFile[] = [{ path: `main.${ext}`, content: starters[language] }];
    const solved: ProjectFile[] = [{ path: `main.${ext}`, content: solutions[language] }];
    for (const helper of d.helpers ?? []) {
      files.push({ path: `${helper.name}.${ext}`, content: helper.starter?.[language] ?? helper.code[language], readOnly: !helper.editable });
      solved.push({ path: `${helper.name}.${ext}`, content: helper.code[language], readOnly: !helper.editable });
    }
    if (d.ownTests) {
      files.push({ path: `pruebas.${ext}`, content: d.ownTests[language] });
      solved.push({ path: `pruebas.${ext}`, content: d.ownTests[language] });
    }
    files.push(...(d.resources ?? [])); solved.push(...(d.resources ?? []));
    projects[language] = { version: 1, entrypoint: `main.${ext}`, files, ...(d.ownTests ? { testEntrypoint: `pruebas.${ext}` } : {}), ...(d.previous ? { previousStep: `logica-${d.previous}` } : {}) };
    projectSolutions[language] = solved;
  }
  const explanation = `${d.theory}\n\nPlan: separa las operaciones, comprueba la entrada, ejecuta el recorrido y devuelve el resultado calculado. Abre cada archivo de la solución para seguir la transferencia de datos. Las pruebas oficiales evalúan resultados independientes: no certifican organización interna ni calidad de una suite por un contador que imprima el programa.`;
  const e: ProjectLesson = {
    slug: d.key, title: d.key, description: d.problem.split(". ")[0].slice(0, 290), category: "Fundamentos", level: "INTERMEDIATE", minutes: 25,
    statement: `${d.problem}\n\nContrato FUNCTION: solve recibe ${d.input} y devuelve ${d.output}. No leas stdin. Python exporta def solve; JavaScript usa CommonJS (module.exports = solve); TypeScript export function solve compila a CommonJS. Los módulos se importan con from reglas import nombre, require('./reglas') o import { nombre } from './reglas', respectivamente.\n\n${d.theory}\n\nCriterios de aceptación: respetar las salidas descritas, cubrir vacío y límites permitidos, y mantener separados los archivos del proyecto. Cada caso parte de un disco aislado limpio. Los archivos solo duran durante esa ejecución: no se conservan entre envíos. Puedes escribir y reabrir en la misma ejecución.`,
    constraints: ["Hasta 100 elementos; enteros entre -1000 y 1000 salvo límites más específicos.", "No instales paquetes. Los recursos públicos no contienen respuestas de casos oficiales.", "El disco del sandbox no es la base de datos de Itera ni el disco del servidor web."],
    objective: d.problem.split(". ")[0], practiceGoals: [d.problem.split(". ")[0], "Comprobar casos límite y explicar el reparto de responsabilidades."], prerequisites: ["Bloques anteriores de esta ruta; los prerrequisitos orientan y no bloquean."],
    hints: d.hints, explanation, explanations: { python: explanation, javascript: explanation, typescript: explanation },
    python: solutions.python, javascript: solutions.javascript, typescript: solutions.typescript, starters,
    typescriptContract: `const __iteraContract: (data: ${d.input}) => ${d.output} = solve;`,
    projects, projectSolutions, tests: d.cases.map(([input, expected], i) => ({ input, expected, visible: i < 2, ...(produced ? { expectedFiles: [{ path: produced.path, content: produced.contents[i] }] } : {}) })),
    complexity: "Cuenta los elementos recorridos, las copias y el tamaño del texto leído o escrito; leer todo un archivo requiere memoria proporcional a su contenido.",
    commonErrors: ["Confundir una ruta local de módulo con un paquete externo.", "Suponer que el disco se conserva entre envíos.", "Escribir un archivo sin volver a abrirlo para verificar sus datos."],
  };
  if (produced) {
    const format = produced.path.endsWith(".json") ? " JSON UTF-8 compacto, sin espacios de separación ni salto final. Python: json.dump(datos, archivo, ensure_ascii=False, separators=(',', ':')); Node: JSON.stringify(datos). Conserva el orden de las listas y de inserción de las claves: stock inicial antes de productos nuevos; en tareas, titulo antes de hecha." : " Texto UTF-8 exacto, sin añadir salto final.";
    e.statement += `\n\nArchivo evaluado: ${produced.path}, que debe crearse durante esta ejecución y no forma parte de la plantilla.${format} Los recursos iniciales no se modifican: carga el recurso y guarda una instantánea nueva. Se comprueba el contenido del archivo además del valor devuelto; devolver el resultado sin escribir no basta.`;
    e.explanation += `\n\nPersistencia comprobada: crea y reabre ${produced.path}.${format} Después del guardado se consulta el archivo producido, sin sobrescribir recursos iniciales. Esto verifica un solo proceso, no dos procesos secuenciales.`;
    e.explanations = { python: e.explanation, javascript: e.explanation, typescript: e.explanation };
    e.constraints.push(`Genera ${produced.path} con el formato indicado; no lo añadas como recurso inicial.`);
  }
  // La explicación contrasta lenguajes: no reemplazar JavaScript por TypeScript
  // al adaptar el enunciado, porque cambiaría el significado de CommonJS.
  e.statements = { python: e.statement, javascript: e.statement, typescript: e.statement };
  fundamentalsProjectLessons.set(d.key, e);
  return e;
}

const imports = { javascript: "const { transformar } = require('./reglas');" };
const moduleRule: Code = { python: "def transformar(valor):\n    return valor * 4\n", javascript: "function transformar(valor) { return valor * 4; }\nmodule.exports = { transformar };\n", typescript: "export function transformar(valor: number): number { return valor * 4; }\n" };
const typedImport = "// import vincula el nombre exportado del módulo local.\n";
projectLesson({ key: "importa-preparado", problem: "Importa transformar desde el módulo reglas preparado y devuelve su resultado para el entero recibido. El módulo multiplica por cuatro; no copies su implementación en main.", input: "number", output: "number", code: { python: "from reglas import transformar\nreturn transformar(data)", javascript: `${imports.javascript}\nreturn transformar(data);`, typescript: "const { transformar } = require('./reglas') as { transformar: (valor: number) => number };\nreturn transformar(data);" }, helpers: [{name:"reglas",code:moduleRule}], cases: [[3,12],[0,0],[-2,-8],[9,36]], hints: ["El módulo ya contiene la operación.","Importa el nombre transformar, no el archivo como un número.","Devuelve transformar(data) desde main."], theory: "Un módulo es un archivo real con nombres reutilizables. En Python from reglas import transformar busca reglas.py; en Node require('./reglas') resuelve el archivo local. CommonJS es una opción de Node, no la única forma de módulos JavaScript. En TypeScript el import real del punto de entrada enlaza el nombre exportado por reglas; import/export se compila a CommonJS y se comprueban los tipos de todos los archivos." });
const square: Code = { python: "def cuadrado(n):\n    return n * n\n", javascript: "function cuadrado(n) { return n * n; }\nmodule.exports = { cuadrado };\n", typescript: "export function cuadrado(n: number): number { return n * n; }\n" };
const squareStarter: Code = { python: "def cuadrado(n):\n    return 0\n", javascript: "function cuadrado(n) { return 0; }\nmodule.exports = { cuadrado };\n", typescript: "export function cuadrado(n: number): number { return 0; }\n" };
projectLesson({ key: "extrae-modulo", problem: "Separa tu función cuadrado en reglas y úsala desde main para devolver el cuadrado del entero recibido. Completa ambos archivos editables.", input: "number", output: "number", code: { python: "from reglas import cuadrado\nreturn cuadrado(data)", javascript: "const { cuadrado } = require('./reglas');\nreturn cuadrado(data);", typescript: "const { cuadrado } = require('./reglas') as { cuadrado: (n: number) => number };\nreturn cuadrado(data);" }, helpers: [{name:"reglas",code:square,starter:squareStarter,editable:true}], cases: [[3,9],[0,0],[-4,16],[7,49]], hints: ["La función debe vivir en reglas.","Exporta el mismo nombre que importas.","Implementa n * n y llama cuadrado(data)."], theory: "Separar una función exige acordar su nombre y contrato entre archivos. En JS module.exports = { cuadrado } exporta un objeto con esa función. En TS export declara el nombre público; conserva tipos estrictos." });
