projectLesson({key:"gastos-validacion",previous:"gastos-registro",problem:"Gestor de gastos, hito 2: conserva el resumen, añade validación y pruebas. Rechaza importe negativo o categoría distinta de casa/ocio. Devuelve {total, porCategoria, rechazados}; un inválido no interrumpe el resto. Completa pruebas propias para vacío, cero y rechazo, sin sustituir los casos oficiales.",input:"{ categoria: string; importe: number }[]",output:"{ total: number; porCategoria: Record<string, number>; rechazados: number }",code:{python:"total = 0\npor_categoria = {}\nrechazados = 0\nfor m in data:\n    if m['importe'] < 0 or m['categoria'] not in ['casa', 'ocio']:\n        rechazados += 1\n        continue\n    total += m['importe']\n    c = m['categoria']\n    por_categoria[c] = por_categoria.get(c, 0) + m['importe']\nreturn {'total': total, 'porCategoria': por_categoria, 'rechazados': rechazados}",javascript:"let total = 0; const porCategoria = {}; let rechazados = 0;\nfor (const m of data) { if (m.importe < 0 || (m.categoria !== 'casa' && m.categoria !== 'ocio')) { rechazados++; continue; } total += m.importe; porCategoria[m.categoria] = (porCategoria[m.categoria] ?? 0) + m.importe; }\nreturn { total, porCategoria, rechazados };",typescript:"let total = 0; const porCategoria: Record<string, number> = {}; let rechazados = 0;\nfor (const m of data) { if (m.importe < 0 || (m.categoria !== 'casa' && m.categoria !== 'ocio')) { rechazados++; continue; } total += m.importe; porCategoria[m.categoria] = (porCategoria[m.categoria] ?? 0) + m.importe; }\nreturn { total, porCategoria, rechazados };"},cases:[[[{categoria:"casa",importe:5},{categoria:"ocio",importe:-1},{categoria:"otra",importe:3}],{total:5,porCategoria:{casa:5},rechazados:2}],[[],{total:0,porCategoria:{},rechazados:0}],[[{categoria:"ocio",importe:0},{categoria:"casa",importe:2}],{total:2,porCategoria:{ocio:0,casa:2},rechazados:0}]],hints:["Valida antes de sumar.","continue pasa al siguiente elemento del bucle.","Conserva la prueba de cero: no es un rechazo."],theory:`${expenseTheory} continue salta el resto del paso actual. Este hito añade un contrato nuevo y tiene identidad independiente. Puedes copiar explícitamente tus archivos anteriores o empezar desde esta plantilla. Ejecutar tus pruebas no concede finalización.`,ownTests:ownExpenseTests});

const inventoryRule: Code = {
  python:"def aplicar(stock, movimientos):\n    rechazados = 0\n    for m in movimientos:\n        clave = m['producto']\n        siguiente = stock.get(clave, 0) + m['cambio']\n        if siguiente < 0:\n            rechazados += 1\n        else:\n            stock[clave] = siguiente\n    return rechazados\n",
  javascript:"function aplicar(stock, movimientos) { let rechazados = 0; for (const m of movimientos) { const siguiente = (stock[m.producto] ?? 0) + m.cambio; if (siguiente < 0) rechazados++; else stock[m.producto] = siguiente; } return rechazados; }\nmodule.exports = { aplicar };\n",
  typescript:"export function aplicar(stock: Record<string, number>, movimientos: { producto: string; cambio: number }[]): number { let rechazados = 0; for (const m of movimientos) { const siguiente = (stock[m.producto] ?? 0) + m.cambio; if (siguiente < 0) rechazados++; else stock[m.producto] = siguiente; } return rechazados; }\n",
};
