const agendaRule: Code = {
  python:"def aplicar(tareas, comandos):\n    for comando in comandos:\n        if comando['accion'] == 'crear':\n            tareas.append({'titulo': comando['titulo'], 'hecha': False})\n        elif comando['accion'] == 'completar':\n            for tarea in tareas:\n                if tarea['titulo'] == comando['titulo']: tarea['hecha'] = True\n    return tareas\n",
  javascript:"function aplicar(tareas, comandos) { for (const c of comandos) { if (c.accion === 'crear') tareas.push({titulo:c.titulo, hecha:false}); else if (c.accion === 'completar') for (const t of tareas) if (t.titulo === c.titulo) t.hecha = true; } return tareas; }\nmodule.exports = { aplicar };\n",
  typescript:"export type Tarea = { titulo: string; hecha: boolean };\nexport function aplicar(tareas: Tarea[], comandos: {accion:string;titulo:string}[]): Tarea[] { for (const c of comandos) { if (c.accion === 'crear') tareas.push({titulo:c.titulo, hecha:false}); else if (c.accion === 'completar') for (const t of tareas) if (t.titulo === c.titulo) t.hecha = true; } return tareas; }\n",
};
